### app/views/layouts/_theme_preference.html.erb
<%= javascript_tag nonce: true do %>
  const theme = localStorage.getItem("theme")
  if (theme && theme !== "auto") {
    document.documentElement.dataset.theme = theme
  }
<% end %>
